function clock(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(Math.floor(t%60)).padStart(2,'0');}
function render(){const next=M.scene(time),s=scenes[next];if(next!==current){current=next;for(const [id,v]of Object.entries({sceneKind:`0${next+1} / ${s.kind}`,sceneLabel:`0${next+1} / ${s.kind}`,visualTitle:s.visual,scaleName:s.scale,detailTitle:s.detail,viewNumber:'0'+(next+1),viewTitle:s.title,viewText:s.text,takeaway:s.take,question:s.question,answer:s.answer,caption:s.caption,detailNote:s.note,sceneSource:s.source}))$(id).textContent=v;$('check').open=false;$('cellScene').setAttribute('aria-label',s.visual+' '+s.caption);$('cellDetail').setAttribute('aria-label',s.detail+'. '+s.note);document.querySelectorAll('[data-view]').forEach((b,i)=>{if(i===next)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});}
 ['routeControls','damageControls','repairControls','fateControls'].forEach((id,i)=>$(id).hidden=i!==next);$('film').classList.toggle('no-labels',!$('labels').checked);$('next').disabled=next===3;[routeScene,damageScene,repairScene,fateScene][next]();$('cellScene').setAttribute('aria-label',$('visualTitle').textContent+'. '+$('meaning').textContent);$('clock').textContent=clock(time)+' / '+clock(duration);$('timeline').value=time;
}
function status(s){$('playerStatus').textContent=s;}
function setPlaying(on){playing=on;last=0;$('play').textContent=on?'Ⅱ Anhalten':time>=duration?'↺ Erneut abspielen':'▶ Fortsetzen';$('play').setAttribute('aria-label',on?'Animation anhalten':'Animation abspielen');if(on&&!raf)raf=requestAnimationFrame(tick);}
function seek(t){setPlaying(false);time=cl(Number(t),0,duration);render();status('Pausiert · '+scenes[M.scene(time)].nav+'.');}
function tick(ts){raf=0;if(!playing)return;if(!last)last=ts;const dt=Math.min((ts-last)/1000,.12);last=ts;const r=M.nextTime(time,dt,Number($('speed').value),$('pauseBetween').checked);time=r.time;if(!r.playing){setPlaying(false);status(time>=duration?'Phase 04 abgeschlossen. Weitere Zellverläufe lassen sich zum Vergleich auswählen.':'Neue Ansicht · '+scenes[M.scene(time)].nav+'. Mit Fortsetzen abspielen.');}if(ts-frame>32||!playing){render();frame=ts;}if(playing)raf=requestAnimationFrame(tick);}
function sync(group,value){document.querySelectorAll('[data-'+group+']').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset[group]===value)));}
$('views').innerHTML=scenes.map((s,i)=>`<button type="button" data-view="${i}"><small>0${i+1} · ${clock(starts[i])}</small>${s.nav}</button>`).join('');$('views').onclick=e=>{const b=e.target.closest('[data-view]');if(b)seek(starts[Number(b.dataset.view)]);};
$('play').onclick=()=>{if(playing){setPlaying(false);status('Pausiert.');return;}if(time>=duration){time=0;render();}setPlaying(true);status('Animation läuft · Filmzeit ist keine biologische Prozesszeit.');};$('restart').onclick=()=>seek(0);$('next').onclick=()=>seek(starts[Math.min(3,current+1)]);$('timeline').oninput=e=>seek(e.target.value);$('labels').onchange=render;
document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{route=b.dataset.route;sync('route',route);seek(22);status('Wirkungsweg gewählt · Ergebnis gezeigt. Der Wiederholknopf zeigt den Ablauf.');});$('repeatRoute').onclick=()=>{seek(0);setPlaying(true);};
document.querySelectorAll('[data-lesion]').forEach(b=>b.onclick=()=>{$('intact').checked=false;seek({base:29,ssb:36,dsb:45}[b.dataset.lesion]);});$('intact').onchange=()=>{setPlaying(false);render();status($('intact').checked?'Unbeschädigte Referenz · Film pausiert.':'Gewähltes Schadensbild · Film pausiert.');};
