document.querySelectorAll('[data-fate]').forEach(b=>b.onclick=()=>{fateChoice=b.dataset.fate;sync('fate',fateChoice);seek(114);status('Alternativer Zellverlauf gewählt · keine Vorhersage aus dem vorigen Schaden.');});$('repeatFate').onclick=()=>{seek(82);setPlaying(true);};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($('film').requestFullscreen)await $('film').requestFullscreen();else status('Großansicht wird von diesem Browser nicht unterstützt.');}catch{status('Großansicht ist hier nicht verfügbar.');}};document.addEventListener('fullscreenchange',()=>{$('fullscreen').textContent=document.fullscreenElement?'⛶ Verkleinern':'⛶ Großansicht';});document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){setPlaying(false);status('Pausiert, weil die Seite im Hintergrund ist.');}});
